<?php
require_once __DIR__ . '/auth.php';
$admin_title='Akun admin';$admin_active='account';$errors=[];$username=$admin['username'];$email=$admin['email'];
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$username=trim((string)($_POST['username']??''));$email=trim((string)($_POST['email']??''));$current=(string)($_POST['current_password']??'');$new=(string)($_POST['new_password']??'');$confirm=(string)($_POST['confirm_password']??'');
 if(strlen($username)<4||!preg_match('/^[a-zA-Z0-9_.-]+$/',$username))$errors[]='Username minimal 4 karakter dan hanya boleh memakai huruf, angka, titik, garis bawah, atau tanda hubung.';
 if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Email tidak valid.';
 $st=db()->prepare('SELECT password_hash FROM admins WHERE id=:id');$st->execute(['id'=>$admin['id']]);$row=$st->fetch();
 if($new!==''&&(!password_verify($current,$row['password_hash']??'')||strlen($new)<12||$new!==$confirm))$errors[]='Untuk mengganti password, password lama harus benar, password baru minimal 12 karakter, dan konfirmasi harus cocok.';
 if(!$errors){try{if($new!=='')$up=db()->prepare('UPDATE admins SET username=:u,email=:e,password_hash=:p WHERE id=:id');else $up=db()->prepare('UPDATE admins SET username=:u,email=:e WHERE id=:id');$params=['u'=>$username,'e'=>$email,'id'=>$admin['id']];if($new!=='')$params['p']=password_hash($new,PASSWORD_DEFAULT);$up->execute($params);$_SESSION['admin_username']=$username;flash('success','Informasi akun berhasil diperbarui.');redirect('account.php');}catch(PDOException $e){$errors[]='Tidak bisa menyimpan. Username atau email mungkin sudah dipakai.';}}
}
$admin_title='Akun admin';require __DIR__.'/_layout-top.php';
?>
<section class="admin-panel"><div class="admin-panel-head"><div><h2>Profil pengelola</h2><p>Gunakan email aktif dan jangan gunakan password yang dipakai di akun lain.</p></div></div><div class="admin-panel-body"><?php foreach($errors as $e): ?><div class="alert error"><?= h($e) ?></div><?php endforeach; ?><form method="post" class="admin-form" autocomplete="off"><?= csrf_field() ?><div><label for="username">Username</label><input class="field" id="username" name="username" value="<?= h($username) ?>" required minlength="4"></div><div><label for="email">Email</label><input class="field" id="email" name="email" type="email" value="<?= h($email) ?>" required></div><div class="span-2" style="border-top:1px solid var(--line);padding-top:18px"><strong style="font-size:12px">Ganti password (opsional)</strong><p class="admin-form-hint">Kosongkan password baru jika hanya mengubah username atau email.</p></div><div><label for="current_password">Password saat ini</label><input class="field" id="current_password" type="password" name="current_password" autocomplete="current-password"></div><div><label for="new_password">Password baru (min. 12 karakter)</label><input class="field" id="new_password" type="password" name="new_password" minlength="12" autocomplete="new-password"></div><div><label for="confirm_password">Konfirmasi password baru</label><input class="field" id="confirm_password" type="password" name="confirm_password" minlength="12" autocomplete="new-password"></div><div class="span-2 admin-form-actions"><button class="button button-dark" type="submit">Simpan akun <span>↗</span></button></div></form></div></section>
